"""Tilføjer adgangskontrol til din nemlig-MCP. Ingen loginoplysninger i koden."""
from pathlib import Path
root = Path(__file__).resolve().parent
if not (root / "src" / "server.ts").exists():
    raise SystemExit("Læg denne fil i øverste mappe i nemlig-mcp-projektet.")
server = 'import { createHash, timingSafeEqual } from \'node:crypto\';\nimport { StreamableHTTPServerTransport } from \'@modelcontextprotocol/sdk/server/streamableHttp.js\';\nimport Fastify, { type FastifyInstance, type RouteHandlerMethod } from \'fastify\';\nimport { config } from \'./config.js\';\nimport { credentialsFrom, MissingCredentialsError } from \'./credentials.js\';\nimport { createMcpServer, SERVER_NAME, SERVER_VERSION } from \'./mcp.js\';\nimport type { SessionManager } from \'./sessions.js\';\n\n/** JSON-RPC error code for an unhandled server-side failure. */\nconst INTERNAL_ERROR = -32_603;\n\nexport function createHttpServer(sessions: SessionManager): FastifyInstance {\n  // Remote deployments must never expose basket tools without authentication.\n  // Use an independently generated, high-entropy secret; never use Nemlig\'s password.\n  const apiKey = process.env[\'MCP_API_KEY\']?.trim();\n  if (process.env[\'NODE_ENV\'] === \'production\' && (!apiKey || apiKey.length < 32)) {\n    throw new Error(\'MCP_API_KEY must be set to a strong secret (at least 32 characters) in production\');\n  }\n  const app = Fastify({ logger: { level: process.env[\'LOG_LEVEL\'] ?? \'info\' } });\n\n  if (apiKey) {\n    app.addHook(\'onRequest\', async (request, reply) => {\n      if (request.url.split(\'?\')[0] !== \'/mcp\') return;\n      const authorization = request.headers.authorization;\n      const supplied = authorization?.startsWith(\'Bearer \') ? authorization.slice(7) : undefined;\n      // Constant-time comparison of fixed-size digests; avoids leaking the key.\n      const expectedDigest = createHash(\'sha256\').update(apiKey).digest();\n      const suppliedDigest = createHash(\'sha256\').update(supplied ?? \'\').digest();\n      if (!supplied || !timingSafeEqual(expectedDigest, suppliedDigest)) {\n        reply.header(\'WWW-Authenticate\', \'Bearer realm="nemlig-mcp"\');\n        return reply.code(401).send({ error: \'Unauthorized\' });\n      }\n    });\n  }\n\n\n  app.get(\'/health\', async () => ({\n    status: \'ok\',\n    server: SERVER_NAME,\n    version: SERVER_VERSION,\n  }));\n\n  /**\n   * Stateless streamable HTTP: a transport and MCP server per request. The state\n   * worth keeping — the Nemlig login — lives in the session manager and on disk,\n   * so a client reconnecting, or the container restarting, costs nothing.\n   */\n  app.post(\'/mcp\', async (request, reply) => {\n    let credentials;\n    try {\n      credentials = credentialsFrom(request.headers);\n    } catch (error) {\n      if (!(error instanceof MissingCredentialsError)) throw error;\n      await reply.code(401).send(rpcError(error.message));\n      return;\n    }\n\n    const mcpServer = createMcpServer(sessions, credentials);\n    const transport = new StreamableHTTPServerTransport({\n      sessionIdGenerator: undefined,\n      enableJsonResponse: true,\n    });\n\n    reply.raw.on(\'close\', () => {\n      void transport.close();\n      void mcpServer.close();\n    });\n\n    try {\n      await mcpServer.connect(transport);\n      reply.hijack();\n      await transport.handleRequest(request.raw, reply.raw, request.body);\n    } catch (error) {\n      request.log.error({ err: error }, \'MCP request failed\');\n      if (!reply.raw.headersSent) {\n        reply.raw.writeHead(500, { \'Content-Type\': \'application/json\' });\n        reply.raw.end(JSON.stringify(rpcError(\'Internal server error\')));\n      }\n    }\n  });\n\n  // Stateless mode has no stream to resume and no session to delete.\n  const methodNotAllowed: RouteHandlerMethod = async (_request, reply) =>\n    reply.code(405).send(rpcError(\'Method not allowed. This server is stateless; send requests as HTTP POST.\'));\n  app.get(\'/mcp\', methodNotAllowed);\n  app.delete(\'/mcp\', methodNotAllowed);\n\n  return app;\n}\n\nfunction rpcError(message: string) {\n  return { jsonrpc: \'2.0\', error: { code: INTERNAL_ERROR, message }, id: null };\n}\n'
render = 'services:\n  - type: web\n    name: nemlig-mcp-private\n    runtime: docker\n    plan: starter\n    healthCheckPath: /health\n    envVars:\n      - key: NODE_ENV\n        value: production\n      - key: NEMLIG_ALLOW_HEADER_CREDENTIALS\n        value: "false"\n      - key: MCP_API_KEY\n        sync: false\n      - key: NEMLIG_USERNAME\n        sync: false\n      - key: NEMLIG_PASSWORD\n        sync: false\n'
guide = "# Sikker Claude-forbindelse fra iPhone\n\nDenne version beskytter `/mcp` med `Authorization: Bearer <MCP_API_KEY>`.\nServeren nægter at starte i produktion uden en adgangsnøgle på mindst 32 tegn.\nBrug **ikke** nemlig-adgangskoden som MCP_API_KEY.\n\n1. Brug Render til at oprette en web service fra din *private* GitHub-fork. Vælg Docker runtime og en betalt plan hvis stabil drift er vigtig. Alternativt Blueprint via `render.yaml`. Tjek aktuel pris før valg.\n2. Angiv hemmelige miljøvariabler i Renders dashboard (aldrig i GitHub): `MCP_API_KEY` = en lang tilfældig nøgle, `NEMLIG_USERNAME` og `NEMLIG_PASSWORD` = dit nemlig-login. Sæt `NODE_ENV=production` og `NEMLIG_ALLOW_HEADER_CREDENTIALS=false`.\n3. Vent på successful deployment. Health-check: `https://DIN-SERVER.onrender.com/health` (ingen login-data må vises). `/mcp` skal give HTTP 401 uden Bearer-token.\n4. I Claude på web: Customize > Connectors > Add custom connector. URL: `https://DIN-SERVER.onrender.com/mcp`. Vælg 'No sign in' og tilføj under Request headers `Authorization` med værdien `Bearer DIN-HEMMELIGE-MCP_API_KEY` (med mellemrum efter Bearer). Gem.\n5. Slå forbindelsen til i Claude, og bed først om at **læse** kurven. Test derefter tilføjelse af én vare, og tjek kurven i nemlig-appen.\n\n**Sikkerhed:** Fortæl aldrig Claude/chatten dine kodeord eller API-nøgler. Render-miljøvariabler skal blive hemmelige. MCP-nøglen kan tilbagekaldes ved at rotere `MCP_API_KEY`. Denne adgangsnøgle beskytter mod uautoriserede kald, men løser ikke alle risici ved hosting af tredjepartskode. Hvis du mistænker misbrug, deaktiver tjenesten og skift begge adgangskoder. Ingen betaling eller ordreafgivelse er implementeret.\n\n**Begrænsning:** Gratis Render-tjenester kan sove og have midlertidig lagerplads. Forbindelsen er ikke testet mod din rigtige nemlig-konto. Nemlig tilbyder ikke et offentligt API, og deres interne API kan ændre sig.\n"
(root / "src" / "server.ts").write_text(server)
(root / "render.yaml").write_text(render)
(root / "REMOTE-SETUP-DA.md").write_text(guide)
print("Klar: sikkerhed tilføjet. Kør npm test, og gem ændringerne i GitHub.")
